var collectors = sforce.connection.query("SELECT Id,Collectors__c from Collector__c where Patient__c ='{!Contact.Id}' limit 1");

var records = collectors.getArray("records");
console.log(records);
console.log(records.length);
if(records && records.length>0){
var collectorName = records[0].Collectors__c;
var collectorId = records[0].Id;
window.location.href='/a01/e?CF00NG000000Ar7Vk={!Contact.Name}&CF00NG000000Ar7Vk_lkid={!Contact.Id}&CF00NG000000B0Vp7={!Contact.Account_Name__c}&CF00NG000000B0Vp7_lkid={!Contact.Account_Id__c}&00N1L00000F4i0g='+collectorName+'&retURL=/{!Contact.Id}';
}
else{
window.location.href='/a01/e?CF00NG000000Ar7Vk={!Contact.Name}&CF00NG000000Ar7Vk_lkid={!Contact.Id}&CF00NG000000B0Vp7={!Contact.Account_Name__c}&CF00NG000000B0Vp7_lkid={!Contact.Account_Id__c}&retURL=/{!Contact.Id}';
